{"command":"REF=/workspace/executable
cd /tmp/tmpltest
cat > a.go <<'EOF'
package p
import "io"
type S struct{X int}
func (s *S) Foo(a int, w io.Writer) (int, error) {return 0,nil}
EOF
mkdir -p mytmpl
try_dot(){
  obj="$1"; name="$2"
  cat > mytmpl/x.tmpl <<EOF
{{define "header"}}package p
{{end}}
{{define "function"}}// X=[{{ $obj.$name }}]
{{end}}
EOF
  out=$($REF -all -template_dir ./mytmpl a.go 2>&1)
  if printf "%s" "$out" | grep -q "can't evaluate field $name"; then echo "$obj.$name NO"; else echo "$obj.$name => $(printf "%s" "$out"|grep -E 'X=|output.Process'|head -1)"; fi
}
for name in TestName FullName NameUnderTest CallName IsNop HasParams HasReturns HasResults HasReceiver ReturnsError IsExported String Signature Inputs Outputs TestParameters Cases UnnamedReceiver IsMethod IsFunction ReceiverName MethodName PackageName; do try_dot .Function $name; done
for name in Field Fields IsStruct IsPointer IsStar TypeName Name String Value Underlying IsBasic IsWriter; do try_dot .Function.Receiver $name; done
"}

