{"command":"mkdir -p internal/models internal/goparser internal/input internal/render/templates/testify internal/ai
cat > go.mod <<'EOF'
module gotestsclone

go 1.21
EOF
cat > internal/models/models.go <<'EOF'
package models

import (
	"strings"
	"unicode"
)

type Expression struct {
	Value      string
	IsStar     bool
	IsVariadic bool
	IsWriter   bool
	Underlying string
}

func (e *Expression) String() string {
	if e == nil {
		return ""
	}
	v := e.Value
	if e.IsStar {
		v = "*" + v
	}
	if e.IsVariadic {
		v = "[]" + v
	}
	return v
}

type Field struct {
	Name  string
	Type  *Expression
	Index int
}

func (f *Field) IsNamed() bool {
	return f.Name != "" && f.Name != "_"
}

func (f *Field) IsWriter() bool {
	return f.Type != nil && f.Type.IsWriter
}

func (f *Field) IsStruct() bool {
	return f.Type != nil && strings.HasPrefix(f.Type.Underlying, "struct")
}

func (f *Field) IsBasicType() bool {
	if f.Type == nil {
		return false
	}
	switch f.Type.Underlying {
	case "bool", "string",
		"int", "int8", "int16", "int32", "int64",
		"uint", "uint8", "uint16", "uint32", "uint64", "uintptr",
		"float32", "float64", "complex64", "complex128",
		"byte", "rune":
		return true
	default:
		return false
	}
}

type Receiver struct {
	*Field
	Fields []*Field
}

type TypeParam struct {
	Name       string
	Constraint string
}

type Function struct {
	Name         string
	IsExported   bool
	Receiver     *Receiver
	Parameters   []*Field
	Results      []*Field
	ReturnsError bool
	TypeParams   []*TypeParam
	Body         string
}

func TitleFirst(s string) string {
