{"command":"cat > internal/goparser/goparser.go <<'EOF'
package goparser

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/token"
	"go/types"
	"os"
	"path/filepath"
	"strings"

	"gotestsclone/internal/models"
)

type Parser struct {
	fset         *token.FileSet
	parsedTypes  map[string]string
	typeSpecs    map[string]*ast.TypeSpec
	genericTypes map[string][]string
	src          []byte
}

type fakeImporter struct{}

func (fakeImporter) Import(path string) (*types.Package, error) {
	if path == "unsafe" {
		return types.Unsafe, nil
	}
	return nil, fmt.Errorf("could not import %s", path)
}

// Parse parses the source file at path (plus sibling files in the same
// package for type information) and returns its header and functions.
func (p *Parser) Parse(path string) (*models.Header, []*models.Function, error) {
	return p.parse(path, false)
}

// ParseTestFile parses an existing _test.go file. It behaves like Parse
// except header imports are limited to those of the file itself.
func (p *Parser) ParseTestFile(path string) (*models.Header, []*models.Function, error) {
	return p.parse(path, true)
}

func (p *Parser) parse(path string, testFile bool) (*models.Header, []*models.Function, error) {
	src, err := os.ReadFile(path)
	if err != nil {
		return nil, nil, fmt.Errorf("ioutil.ReadFile: %w", err)
	}
	if len(src) == 0 {
		return nil, nil, nil
	}
	p.src = src
	p.fset = token.NewFileSet()
	p.parsedTypes = make(map[string]string)
	p.typeSpecs = make(map[string]*ast.TypeSpec)
	p.genericTypes = make(map[string][]string)

	target, err := parser.ParseFile(p.fset, path, src, parser.ParseComments|parser.AllErrors)
	if err != nil {
		return nil, nil, fmt.Errorf("target parser.ParseFile(): %w", err)
	}
	header := &models.Header{
		Comments: parseComments(target),
		Package:  target.Name.Name,
		Imports:  parseImports(target),
	}
	if strings.HasSuffix(path, "_test.go") {
		header.Code = goCode(p.fset, src, target)
	}

	// Parse other files in the same directory.
	dir := filepath.Dir(path)
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, nil, fmt.Errorf("ioutil.ReadDir: %w", err)
	}
	var otherFiles []*ast.File
	var otherPaths []string
	for _, e := range entries {
		name := e.Name()
		if strings.HasPrefix(name, ".") || strings.HasSuffix(name, "_test.go") || !strings.HasSuffix(name, ".go") {
			continue
		}
		full := filepath.Join(dir, name)
		f, err := parser.ParseFile(p.fset, full, nil, parser.ParseComments|parser.AllErrors)
		if err != nil {
			return nil, nil, fmt.Errorf("other file parser.ParseFile: %w", err)
		}
		if f.Name.Name != target.Name.Name {
			continue
		}
		otherFiles = append(otherFiles, f)
		otherPaths = append(otherPaths, full)
		if !testFile {
			header.Imports = append(header.Imports, parseImports(f)...)
		}
	}

	// Collect type specifications (first occurrence wins), starting with
	// the target file followed by sibling files in directory order.
	collectSpecs := func(f *ast.File) {
		for _, decl := range f.Decls {
			gd, ok := decl.(*ast.GenDecl)
			if !ok || gd.Tok != token.TYPE {
				continue
			}
			for _, spec := range gd.Specs {
				ts := spec.(*ast.TypeSpec)
				if _, exists := p.typeSpecs[ts.Name.Name]; !exists {
					p.typeSpecs[ts.Name.Name] = ts
					if ts.TypeParams != nil {
						var names []string
						for _, field := range ts.TypeParams.List {
							for _, n := range field.Names {
								names = append(names, n.Name)
							}
						}
						p.genericTypes[ts.Name.Name] = names
					}
				}
			}
		}
	}
	collectSpecs(target)
	for _, f := range otherFiles {
		collectSpecs(f)
	}

	p.initParsedTypes(target, otherFiles, otherPaths, path)

	var funcs []*models.Function
	for _, decl := range target.Decls {
		fd, ok := decl.(*ast.FuncDecl)
		if !ok {
			continue
		}
		if fd.Recv == nil && fd.Name.Name == "init" {
			continue
		}
		funcs = append(funcs, p.parseFunction(fd))
	}
	return header, funcs, nil
}

func parseComments(f *ast.File) []string {
	var comments []string
	for _, g := range f.Comments {
		if g.Pos() >= f.Package {
			continue
		}
		for _, c := range g.List {
			comments = append(comments, c.Text)
		}
		if g != f.Doc {
			comments = append(comments, "")
		}
	}
	return comments
}

func parseImports(f *ast.File) []*models.Import {
	var imports []*models.Import
	for _, spec := range f.Imports {
		imp := &models.Import{Path: spec.Path.Value}
		if spec.Name != nil {
			imp.Name = spec.Name.Name
		}
		imports = append(imports, imp)
	}
	return imports
}

func goCode(fset *token.FileSet, src []byte, f *ast.File) []byte {
	var end token.Pos
	if len(f.Imports) > 0 {
		end = f.Imports[len(f.Imports)-1].End()
	} else {
		end = f.Name.End()
	}
	tf := fset.File(f.Package)
	if tf == nil {
		return nil
	}
	start := tf.Offset(end) + 2
	if start > len(src) || start < 0 {
		return []byte{}
	}
	return src[start:]
}

func (p *Parser) initParsedTypes(target *ast.File, others []*ast.File, otherPaths []string, targetPath string) {
	for _, name := range types.Universe.Names() {
		if tn, ok := types.Universe.Lookup(name).(*types.TypeName); ok {
			p.parsedTypes[name] = types.TypeString(tn.Type().Underlying(), func(q *types.Package) string {
				return q.Name()
			})
		}
	}
	p.parsedTypes["unsafe.Pointer"] = "unsafe.Pointer"

	// Type-check the package (ignoring errors) to learn the underlying
	// type of every defined type name, including type parameters.
	files := []*ast.File{target}
	seen := map[string]bool{targetPath: true}
	for i, f := range others {
		if i < len(otherPaths) && !seen[otherPaths[i]] {
			seen[otherPaths[i]] = true
			files = append(files, f)
		}
	}
	info := &types.Info{Defs: make(map[*ast.Ident]types.Object)}
	conf := types.Config{
		Importer:    fakeImporter{},
		FakeImportC: true,
		Error:       func(error) {},
	}
	pkg, _ := conf.Check(target.Name.Name, p.fset, files, info)
	qual := func(q *types.Package) string {
		if pkg != nil && q == pkg {
			return ""
		}
		if q != nil && q.Path() == target.Name.Name {
			return ""
		}
		return q.Name()
	}
	for id, obj := range info.Defs {
		if obj == nil {
			continue
		}
		if tn, ok := obj.(*types.TypeName); ok {
			p.parsedTypes[id.Name] = types.TypeString(tn.Type().Underlying(), qual)
		}
	}
