	// Results, separating error returns.
	if fd.Type.Results != nil {
		for _, f := range p.parseFields(fd.Type.Results, false) {
			if f.Type != nil && f.Type.Value == "error" && !f.Type.IsStar && !f.Type.IsVariadic {
				fn.ReturnsError = true
				continue
			}
			f.Index = len(fn.Results)
			fn.Results = append(fn.Results, f)
		}
	}
	if fd.Recv != nil && len(fd.Recv.List) > 0 {
		rfs := p.parseFields(fd.Recv, false)
		if len(rfs) > 0 {
			recv := &models.Receiver{Field: rfs[0], Fields: []*models.Field{}}
			recv.Fields = p.structFieldsForType(rfs[0].Type.Value, make(map[string]bool))
			fn.Receiver = recv
		}
	}
	if fn.Receiver != nil {
		base := fn.Receiver.Field.Type.Value
		if i := strings.Index(base, "["); i >= 0 {
			base = base[:i]
		}
		if spec, ok := p.typeSpecs[base]; ok && spec.TypeParams != nil && len(spec.TypeParams.List) > 0 {
			fn.TypeParams = p.parseTypeParams(spec.TypeParams)
		}
	} else if fd.Type.TypeParams != nil {
		fn.TypeParams = p.parseTypeParams(fd.Type.TypeParams)
	}
	return fn
}

func (p *Parser) parseTypeParams(list *ast.FieldList) []*models.TypeParam {
	if list == nil {
		return nil
	}
	var out []*models.TypeParam
	for _, field := range list.List {
		constraint := p.parseExpr(field.Type).String()
		for _, n := range field.Names {
			out = append(out, &models.TypeParam{Name: n.Name, Constraint: constraint})
		}
	}
	return out
}

func (p *Parser) structFieldsForType(name string, seen map[string]bool) []*models.Field {
	out := []*models.Field{}
	if name == "" || strings.Contains(name, "[") || seen[name] {
		return out
	}
	seen[name] = true
	spec, ok := p.typeSpecs[name]
	if !ok {
		return out
	}
	switch t := spec.Type.(type) {
	case *ast.StructType:
		if fs := p.parseFields(t.Fields, true); fs != nil {
			return fs
		}
		return out
	case *ast.Ident:
		return p.structFieldsForType(t.Name, seen)
	default:
		return out
	}
}

func embeddedFieldName(expr ast.Expr) string {
	switch t := expr.(type) {
	case *ast.Ident:
		return t.Name
	case *ast.SelectorExpr:
		return t.Sel.Name
	case *ast.StarExpr:
		return embeddedFieldName(t.X)
	case *ast.IndexExpr:
		return embeddedFieldName(t.X)
	case *ast.IndexListExpr:
		return embeddedFieldName(t.X)
	default:
		return ""
	}
}

func (p *Parser) parseFields(list *ast.FieldList, structMode bool) []*models.Field {
	if list == nil {
		return nil
	}
	var out []*models.Field
	for _, field := range list.List {
		typ := p.parseExpr(field.Type)
		if len(field.Names) == 0 {
			name := ""
			if structMode {
				name = embeddedFieldName(field.Type)
			}
			out = append(out, &models.Field{Name: name, Type: typ, Index: len(out)})
			continue
		}
		for _, n := range field.Names {
			out = append(out, &models.Field{Name: n.Name, Type: typ, Index: len(out)})
		}
	}
	return out
}
