			if _, ok := t.Len.(*ast.BasicLit); !ok {
				valid = false
			}
		}
		v := "[" + lenStr + "]" + elt.String()
		under := ""
		if valid {
			under = v
		}
		return &models.Expression{Value: v, Underlying: under}
	case *ast.MapType:
		k := p.parseExpr(t.Key)
		val := p.parseExpr(t.Value)
		v := "map[" + k.String() + "]" + val.String()
		under := ""
		if k.Underlying != "" && val.Underlying != "" {
			under = v
		}
		return &models.Expression{Value: v, Underlying: under}
	case *ast.ChanType:
		elt := p.parseExpr(t.Value)
		var v string
		switch t.Dir {
		case ast.SEND:
			v = "chan<- " + elt.String()
		case ast.RECV:
			v = "<-chan " + elt.String()
		default:
			v = "chan " + elt.String()
		}
		under := ""
		if elt.Underlying != "" {
			under = v
		}
		return &models.Expression{Value: v, Underlying: under}
	case *ast.FuncType:
		v, valid := p.renderFuncType(t)
		under := ""
		if valid {
			under = v
		}
		return &models.Expression{Value: v, Underlying: under}
	case *ast.StructType:
		parts, valid := p.renderFieldList(t.Fields)
		v := "struct{" + strings.Join(parts, "; ") + "}"
		under := ""
		if valid {
