		}
		return &models.Expression{Value: v, Underlying: under}
	default:
		var buf bytes.Buffer
		_ = format.Node(&buf, p.fset, expr)
		return &models.Expression{Value: buf.String()}
	}
}

func (p *Parser) parseIndex(x ast.Expr, indices []ast.Expr) *models.Expression {
	base := p.parseExpr(x)
	var args []*models.Expression
	var strs []string
	for _, ix := range indices {
		a := p.parseExpr(ix)
		args = append(args, a)
		strs = append(strs, a.String())
	}
	v := base.String() + "[" + strings.Join(strs, ", ") + "]"
	under := ""
	if id, ok := x.(*ast.Ident); ok {
		if params, isGeneric := p.genericTypes[id.Name]; isGeneric {
			if len(args) != len(params) {
				under = "invalid type"
			} else {
				valid := true
				for _, a := range args {
					if a.Underlying == "" {
						valid = false
						break
					}
				}
				if valid {
					under = p.parsedTypes[id.Name]
					for i, param := range params {
						under = strings.ReplaceAll(under, param, args[i].String())
					}
				}
			}
		}
	}
	return &models.Expression{Value: v, Underlying: under}
}

// renderFieldList renders the fields of a field list, preserving field
// groupings. It reports whether all field types have known underlying
// types (and no field declares multiple names).
func (p *Parser) renderFieldList(list *ast.FieldList) ([]string, bool) {
	if list == nil {
		return nil, true
	}
	valid := true
	var parts []string
	for _, field := range list.List {
		if len(field.Names) > 1 {
			valid = false
		}
		var typeStr string
		if ell, ok := field.Type.(*ast.Ellipsis); ok {
			typeStr = "..." + p.parseExpr(ell.Elt).String()
		} else {
			typeStr = p.parseExpr(field.Type).String()
		}
		if p.parseExpr(field.Type).Underlying == "" {
			valid = false
		}
		if len(field.Names) > 0 {
			var names []string
			for _, n := range field.Names {
				names = append(names, n.Name)
			}
			parts = append(parts, strings.Join(names, ", ")+" "+typeStr)
		} else {
			parts = append(parts, typeStr)
		}
	}
	return parts, valid
}

func (p *Parser) renderFuncSignature(t *ast.FuncType) (string, bool) {
	params, pv := p.renderFieldList(t.Params)
	s := "(" + strings.Join(params, ", ") + ")"
	valid := pv
	if t.Results != nil && len(t.Results.List) > 0 {
		results, rv := p.renderFieldList(t.Results)
		valid = valid && rv
		if len(t.Results.List) == 1 && len(t.Results.List[0].Names) == 0 {
			s += " " + results[0]
		} else {
			s += " (" + strings.Join(results, ", ") + ")"
		}
	}
	return s, valid
}

func (p *Parser) renderFuncType(t *ast.FuncType) (string, bool) {
	sig, valid := p.renderFuncSignature(t)
	return "func" + sig, valid
}
