// ConcreteType maps a type-parameter constraint to a concrete type used
// when instantiating generics in generated tests.
func ConcreteType(constraint string) string {
	if strings.Contains(constraint, "|") {
		return strings.TrimSpace(strings.Split(constraint, "|")[0])
	}
	if strings.HasPrefix(constraint, "~") {
		return strings.TrimSpace(constraint[1:])
	}
	if strings.Contains(constraint, "~") {
		return constraint
	}
	if constraint == "any" {
		return "int"
	}
	name := constraint
	if i := strings.LastIndex(name, "."); i >= 0 {
		name = name[i+1:]
	}
	switch name {
	case "Ordered", "Signed", "Unsigned", "Integer", "Float", "Complex":
		return "int"
	default:
		return "string"
	}
}

func FieldType(owner interface{}, f *models.Field) string {
	s := f.Type.String()
	if fn, ok := owner.(*models.Function); ok && fn != nil {
		for _, tp := range fn.TypeParams {
			s = strings.ReplaceAll(s, tp.Name, ConcreteType(tp.Constraint))
		}
	}
	return s
}

