		"Got":          Got,
		"ConcreteType": ConcreteType,
	}
}

func LoadTemplates(templateDir, templateName string) (*template.Template, error) {
	tmpls := template.New("gotests").Funcs(templateFuncs())
	base, err := fs.Sub(templatesFS, "templates")
	if err != nil {
		return nil, err
	}
	if _, err := tmpls.ParseFS(base, "*.tmpl"); err != nil {
		return nil, err
	}
	if templateDir != "" {
		files, err := ioutil.ReadDir(templateDir)
		if err != nil {
			return nil, fmt.Errorf("loading custom templates: %w", fmt.Errorf("ioutil.ReadDir: %w", err))
		}
		var paths []string
		for _, f := range files {
			paths = append(paths, filepath.Join(templateDir, f.Name()))
		}
		if _, err := tmpls.ParseFiles(paths...); err != nil {
			return nil, fmt.Errorf("loading custom templates: %w", fmt.Errorf("tmpls.ParseFiles: %w", err))
