package render

import (
	"go/ast"
	"go/format"
	"go/parser"
	"go/token"
	"path"
	"sort"
	"strconv"
	"strings"
)

type importSpec struct {
	Name string // alias ("" for none)
	Path string // unquoted path
}

func isStdPath(p string) bool {
	first := p
	if i := strings.Index(p, "/"); i >= 0 {
		first = p[:i]
	}
	return !strings.Contains(first, ".")
}

func inferImportName(p string) string {
	base := path.Base(p)
	parts := strings.Split(p, "/")
	// Version suffixes: /v2 or .v2
	if len(parts) > 1 && isVersionSegment(base) {
		base = parts[len(parts)-2]
	}
	if i := strings.LastIndex(base, ".v"); i >= 0 && isVersionSegment(base[i+1:]) {
		base = base[:i]
	}
	if i := strings.Index(base, "-"); i >= 0 {
		base = base[:i]
	}
	if i := strings.Index(base, "."); i >= 0 {
		base = base[:i]
	}
	return base
}

func isVersionSegment(s string) bool {
	if len(s) < 2 || s[0] != 'v' {
		return false
	}
	for _, c := range s[1:] {
		if c < '0' || c > '9' {
			return false
		}
	}
	return true
}

func (s importSpec) effectiveName() string {
	if s.Name != "" {
		return s.Name
	}
	return inferImportName(s.Path)
}

func collectFileLevelNames(f *ast.File) map[string]bool {
	names := make(map[string]bool)
	for _, d := range f.Decls {
		switch t := d.(type) {
		case *ast.FuncDecl:
			names[t.Name.Name] = true
		case *ast.GenDecl:
			if t.Tok == token.IMPORT {
				continue
			}
			for _, spec := range t.Specs {
				switch sp := spec.(type) {
				case *ast.ValueSpec:
					for _, n := range sp.Names {
						names[n.Name] = true
					}
				case *ast.TypeSpec:
					names[sp.Name.Name] = true
				}
			}
		}
	}
	return names
}

func collectLocalNames(node ast.Node) map[string]bool {
	names := make(map[string]bool)
	ast.Inspect(node, func(n ast.Node) bool {
		switch t := n.(type) {
		case *ast.FieldList:
			for _, field := range t.List {
				for _, name := range field.Names {
					names[name.Name] = true
				}
			}
		case *ast.ValueSpec:
			for _, name := range t.Names {
				names[name.Name] = true
			}
		case *ast.TypeSpec:
			names[t.Name.Name] = true
		case *ast.AssignStmt:
			if t.Tok == token.DEFINE {
				for _, lhs := range t.Lhs {
					if id, ok := lhs.(*ast.Ident); ok {
						names[id.Name] = true
					}
				}
			}
		case *ast.RangeStmt:
			if t.Tok == token.DEFINE {
				if id, ok := t.Key.(*ast.Ident); ok {
					names[id.Name] = true
				}
				if id, ok := t.Value.(*ast.Ident); ok {
					names[id.Name] = true
				}
			}
		}
		return true
	})
	return names
}

func collectSelectors(node ast.Node, shadow map[string]bool, used map[string]bool) {
	ast.Inspect(node, func(n ast.Node) bool {
		if sel, ok := n.(*ast.SelectorExpr); ok {
			if id, ok := sel.X.(*ast.Ident); ok {
				if !shadow[id.Name] {
					used[id.Name] = true
				}
			}
		}
		return true
	})
}

func collectUsedQualifiers(f *ast.File) map[string]bool {
	fileLevel := collectFileLevelNames(f)
	used := make(map[string]bool)
	for _, d := range f.Decls {
		if gd, ok := d.(*ast.GenDecl); ok && gd.Tok == token.IMPORT {
			continue
		}
		shadow := make(map[string]bool)
		for k := range fileLevel {
			shadow[k] = true
		}
		if fd, ok := d.(*ast.FuncDecl); ok {
			for k := range collectLocalNames(fd) {
				shadow[k] = true
			}
			// The function name itself is not a selector shadow in its
			// own signature types; remove it so a package qualifier
			// spelled like the function is still seen in signature.
			delete(shadow, fd.Name.Name)
		}
		collectSelectors(d, shadow, used)
	}
	// Comments cannot contain selector expressions.
	return used
}

var extraKnownImports = map[string]string{
	"assert":  "github.com/stretchr/testify/assert",
	"require": "github.com/stretchr/testify/require",
	"mock":    "github.com/stretchr/testify/mock",
	"suite":   "github.com/stretchr/testify/suite",
	"cmp":     "github.com/google/go-cmp/cmp",
}

var stdOverrides = map[string]string{
	"rand":     "math/rand",
	"template": "text/template",
}

// ProcessImports formats src and fixes its import declarations,
// mimicking golang.org/x/tools/imports.Process for the cases this tool
// generates.
func ProcessImports(filename string, src []byte) ([]byte, error) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, filename, src, parser.ParseComments|parser.AllErrors)
	if err != nil {
		return nil, err
	}
	used := collectUsedQualifiers(f)

	var raw []importSpec
	type rawInfo struct {
		spec  importSpec
		paren bool
	}
	var rawInfos []rawInfo
	for _, d := range f.Decls {
		gd, ok := d.(*ast.GenDecl)
		if !ok || gd.Tok != token.IMPORT {
			continue
		}
		for _, s := range gd.Specs {
			is := s.(*ast.ImportSpec)
			p, _ := strconv.Unquote(is.Path.Value)
			spec := importSpec{Path: p}
			if is.Name != nil {
				spec.Name = is.Name.Name
			}
			raw = append(raw, spec)
			rawInfos = append(rawInfos, rawInfo{spec: spec, paren: gd.Lparen.IsValid()})
		}
	}

	seen := make(map[importSpec]bool)
	var final []importSpec
	addSpec := func(s importSpec) {
		if !seen[s] {
			seen[s] = true
			final = append(final, s)
		}
	}
	have := make(map[string]bool)
	for _, s := range raw {
		keep := false
		if s.Name == "_" || s.Name == "." {
			keep = true
		} else if used[s.effectiveName()] {
			keep = true
		}
		if keep {
			addSpec(s)
			have[s.effectiveName()] = true
		}
	}
	for name := range used {
		if have[name] {
			continue
		}
		if p, ok := extraKnownImports[name]; ok {
			addSpec(importSpec{Path: p})
			continue
		}
		if p, ok := stdOverrides[name]; ok {
			addSpec(importSpec{Path: p})
			continue
		}
		if p, ok := stdImportByName[name]; ok {
			addSpec(importSpec{Path: p})
			continue
		}
	}

	// Split off the C pseudo-import.
	var cSpec *importSpec
	var rest []importSpec
	for _, s := range final {
		if s.Path == "C" && s.Name == "" {
			cp := s
			cSpec = &cp
		} else {
			rest = append(rest, s)
		}
	}
	sortSpecs := func(list []importSpec) {
		sort.Slice(list, func(i, j int) bool {
			if list[i].Path != list[j].Path {
				return list[i].Path < list[j].Path
			}
			return list[i].Name < list[j].Name
		})
	}
	var std, ext []importSpec
	for _, s := range rest {
		if isStdPath(s.Path) {
			std = append(std, s)
		} else {
			ext = append(ext, s)
		}
	}
	sortSpecs(std)
	sortSpecs(ext)

	paren := false
	if len(rest) > 1 {
		paren = true
	}
	if len(rest) == 1 {
		for _, ri := range rawInfos {
			if ri.spec == rest[0] && ri.paren {
				paren = true
			}
		}
	}
	importText := buildImportText(cSpec, std, ext, paren)

	// Splice the new import text into the source.
	tf := fset.File(f.Package)
	newSrc := spliceImports(f, tf, src, importText)
	formatted, err := format.Source(newSrc)
	if err != nil {
		// Fall back to formatting the parsed file via format.Node on
		// the spliced source reparse; if that fails, return error.
		return nil, err
	}
	return formatted, nil
}

func formatSpec(s importSpec) string {
	if s.Name != "" {
		return s.Name + " " + strconv.Quote(s.Path)
	}
	return strconv.Quote(s.Path)
}

func buildImportText(cSpec *importSpec, std, ext []importSpec, paren bool) string {
	var b strings.Builder
	if cSpec != nil {
		b.WriteString("import (\n\t\"C\"\n)\n")
	}
	all := append(append([]importSpec{}, std...), ext...)
	if len(all) == 0 {
		return b.String()
	}
	if !paren && len(all) == 1 && len(ext) == 0 {
		b.WriteString("import " + formatSpec(all[0]) + "\n")
		return b.String()
	}
	b.WriteString("import (\n")
	for _, s := range std {
		b.WriteString("\t" + formatSpec(s) + "\n")
	}
	if len(std) > 0 && len(ext) > 0 {
		b.WriteString("\n")
	}
	for _, s := range ext {
		b.WriteString("\t" + formatSpec(s) + "\n")
	}
	b.WriteString(")\n")
	return b.String()
}

func spliceImports(f *ast.File, tf *token.File, src []byte, importText string) []byte {
	var firstDecl, lastDecl *ast.GenDecl
	for _, d := range f.Decls {
		if gd, ok := d.(*ast.GenDecl); ok && gd.Tok == token.IMPORT {
			if firstDecl == nil {
				firstDecl = gd
			}
			lastDecl = gd
		}
	}
	if firstDecl == nil {
		// Insert after the package clause line.
		insert := tf.Offset(f.Name.End())
		for insert < len(src) && src[insert] != '\n' {
			insert++
		}
		if insert < len(src) {
			insert++ // past newline
		}
		var out []byte
		out = append(out, src[:insert]...)
		if importText != "" {
			out = append(out, '\n')
			out = append(out, importText...)
		}
		out = append(out, src[insert:]...)
		return out
	}
	start := tf.Offset(firstDecl.Pos())
	if firstDecl.Doc != nil {
		start = tf.Offset(firstDecl.Doc.Pos())
	}
	end := tf.Offset(lastDecl.End())
	var out []byte
	out = append(out, src[:start]...)
	out = append(out, importText...)
	out = append(out, src[end:]...)
	return out
}
