func isVersionSegment(s string) bool {
	if len(s) < 2 || s[0] != 'v' {
		return false
	}
	for _, c := range s[1:] {
		if c < '0' || c > '9' {
			return false
		}
	}
	return true
}

func (s importSpec) effectiveName() string {
	if s.Name != "" {
		return s.Name
	}
	return inferImportName(s.Path)
}

func collectFileLevelNames(f *ast.File) map[string]bool {
	names := make(map[string]bool)
	for _, d := range f.Decls {
		switch t := d.(type) {
		case *ast.FuncDecl:
			names[t.Name.Name] = true
		case *ast.GenDecl:
			if t.Tok == token.IMPORT {
				continue
			}
			for _, spec := range t.Specs {
				switch sp := spec.(type) {
				case *ast.ValueSpec:
					for _, n := range sp.Names {
						names[n.Name] = true
					}
				case *ast.TypeSpec:
					names[sp.Name.Name] = true
				}
			}
		}
	}
	return names
}

func collectLocalNames(node ast.Node) map[string]bool {
	names := make(map[string]bool)
	ast.Inspect(node, func(n ast.Node) bool {
		switch t := n.(type) {
		case *ast.FieldList:
			for _, field := range t.List {
				for _, name := range field.Names {
					names[name.Name] = true
				}
			}
		case *ast.ValueSpec:
			for _, name := range t.Names {
				names[name.Name] = true
			}
		case *ast.TypeSpec:
			names[t.Name.Name] = true
		case *ast.AssignStmt:
			if t.Tok == token.DEFINE {
				for _, lhs := range t.Lhs {
					if id, ok := lhs.(*ast.Ident); ok {
						names[id.Name] = true
					}
				}
			}
		case *ast.RangeStmt:
			if t.Tok == token.DEFINE {
				if id, ok := t.Key.(*ast.Ident); ok {
					names[id.Name] = true
				}
				if id, ok := t.Value.(*ast.Ident); ok {
					names[id.Name] = true
				}
			}
		}
		return true
	})
	return names
}

func collectSelectors(node ast.Node, shadow map[string]bool, used map[string]bool) {
	ast.Inspect(node, func(n ast.Node) bool {
		if sel, ok := n.(*ast.SelectorExpr); ok {
			if id, ok := sel.X.(*ast.Ident); ok {
				if !shadow[id.Name] {
					used[id.Name] = true
				}
			}
		}
		return true
	})
}

func collectUsedQualifiers(f *ast.File) map[string]bool {
	fileLevel := collectFileLevelNames(f)
	used := make(map[string]bool)
	for _, d := range f.Decls {
		if gd, ok := d.(*ast.GenDecl); ok && gd.Tok == token.IMPORT {
			continue
		}
		shadow := make(map[string]bool)
		for k := range fileLevel {
			shadow[k] = true
		}
		if fd, ok := d.(*ast.FuncDecl); ok {
			for k := range collectLocalNames(fd) {
				shadow[k] = true
			}
			// The function name itself is not a selector shadow in its
			// own signature types; remove it so a package qualifier
			// spelled like the function is still seen in signature.
			delete(shadow, fd.Name.Name)
		}
		collectSelectors(d, shadow, used)
	}
	// Comments cannot contain selector expressions.
	return used
}

