	"template": "text/template",
}

// ProcessImports formats src and fixes its import declarations,
// mimicking golang.org/x/tools/imports.Process for the cases this tool
// generates.
func ProcessImports(filename string, src []byte) ([]byte, error) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, filename, src, parser.ParseComments|parser.AllErrors)
	if err != nil {
		return nil, err
	}
	used := collectUsedQualifiers(f)

	var raw []importSpec
	type rawInfo struct {
		spec  importSpec
		paren bool
	}
	var rawInfos []rawInfo
	for _, d := range f.Decls {
		gd, ok := d.(*ast.GenDecl)
		if !ok || gd.Tok != token.IMPORT {
			continue
		}
		for _, s := range gd.Specs {
			is := s.(*ast.ImportSpec)
			p, _ := strconv.Unquote(is.Path.Value)
			spec := importSpec{Path: p}
			if is.Name != nil {
				spec.Name = is.Name.Name
			}
			raw = append(raw, spec)
			rawInfos = append(rawInfos, rawInfo{spec: spec, paren: gd.Lparen.IsValid()})
		}
	}

	seen := make(map[importSpec]bool)
	var final []importSpec
	addSpec := func(s importSpec) {
		if !seen[s] {
			seen[s] = true
			final = append(final, s)
		}
	}
	have := make(map[string]bool)
	for _, s := range raw {
		keep := false
		if s.Name == "_" || s.Name == "." {
			keep = true
		} else if used[s.effectiveName()] {
			keep = true
		}
		if keep {
			addSpec(s)
			have[s.effectiveName()] = true
		}
	}
	for name := range used {
		if have[name] {
			continue
		}
		if p, ok := extraKnownImports[name]; ok {
			addSpec(importSpec{Path: p})
			continue
		}
		if p, ok := stdOverrides[name]; ok {
			addSpec(importSpec{Path: p})
			continue
		}
		if p, ok := stdImportByName[name]; ok {
			addSpec(importSpec{Path: p})
			continue
		}
	}

	// Split off the C pseudo-import.
	var cSpec *importSpec
	var rest []importSpec
	for _, s := range final {
		if s.Path == "C" && s.Name == "" {
			cp := s
			cSpec = &cp
		} else {
			rest = append(rest, s)
		}
	}
	sortSpecs := func(list []importSpec) {
		sort.Slice(list, func(i, j int) bool {
			if list[i].Path != list[j].Path {
				return list[i].Path < list[j].Path
			}
			return list[i].Name < list[j].Name
		})
	}
	var std, ext []importSpec
	for _, s := range rest {
		if isStdPath(s.Path) {
			std = append(std, s)
		} else {
			ext = append(ext, s)
		}
	}
	sortSpecs(std)
	sortSpecs(ext)

	paren := false
	if len(rest) > 1 {
		paren = true
	}
	if len(rest) == 1 {
		for _, ri := range rawInfos {
			if ri.spec == rest[0] && ri.paren {
				paren = true
			}
		}
	}
	importText := buildImportText(cSpec, std, ext, paren)

	// Splice the new import text into the source.
	tf := fset.File(f.Package)
	newSrc := spliceImports(f, tf, src, importText)
	formatted, err := format.Source(newSrc)
	if err != nil {
		// Fall back to formatting the parsed file via format.Node on
		// the spliced source reparse; if that fails, return error.
		return nil, err
	}
	return formatted, nil
}

func formatSpec(s importSpec) string {
	if s.Name != "" {
		return s.Name + " " + strconv.Quote(s.Path)
	}
	return strconv.Quote(s.Path)
}

func buildImportText(cSpec *importSpec, std, ext []importSpec, paren bool) string {
	var b strings.Builder
	if cSpec != nil {
		b.WriteString("import (\n\t\"C\"\n)\n")
	}
	all := append(append([]importSpec{}, std...), ext...)
	if len(all) == 0 {
		return b.String()
	}
	if !paren && len(all) == 1 && len(ext) == 0 {
		b.WriteString("import " + formatSpec(all[0]) + "\n")
		return b.String()
	}
	b.WriteString("import (\n")
	for _, s := range std {
		b.WriteString("\t" + formatSpec(s) + "\n")
	}
	if len(std) > 0 && len(ext) > 0 {
		b.WriteString("\n")
	}
	for _, s := range ext {
		b.WriteString("\t" + formatSpec(s) + "\n")
	}
	b.WriteString(")\n")
	return b.String()
}

func spliceImports(f *ast.File, tf *token.File, src []byte, importText string) []byte {
	var firstDecl, lastDecl *ast.GenDecl
	for _, d := range f.Decls {
		if gd, ok := d.(*ast.GenDecl); ok && gd.Tok == token.IMPORT {
			if firstDecl == nil {
				firstDecl = gd
			}
			lastDecl = gd
		}
	}
	if firstDecl == nil {
		// Insert after the package clause line.
		insert := tf.Offset(f.Name.End())
		for insert < len(src) && src[insert] != '\n' {
			insert++
		}
		if insert < len(src) {
			insert++ // past newline
		}
		var out []byte
		out = append(out, src[:insert]...)
		if importText != "" {
			out = append(out, '\n')
			out = append(out, importText...)
		}
		out = append(out, src[insert:]...)
		return out
	}
	start := tf.Offset(firstDecl.Pos())
	if firstDecl.Doc != nil {
		start = tf.Offset(firstDecl.Doc.Pos())
	}
	end := tf.Offset(lastDecl.End())
	var out []byte
	out = append(out, src[:start]...)
	out = append(out, importText...)
	out = append(out, src[end:]...)
	return out
}
