func cleanResponse(response string) string {
	code := strings.TrimSpace(response)
	code = strings.TrimPrefix(code, "```go")
	code = strings.TrimPrefix(code, "```")
	code = strings.TrimSuffix(code, "```")
	code = strings.TrimSpace(code)
	return code
}

func formatExpr(fset *token.FileSet, expr ast.Expr) string {
	switch t := expr.(type) {
	case *ast.BasicLit:
		return t.Value
	case *ast.Ident:
		return t.Name
	case *ast.CompositeLit:
		var buf bytes.Buffer
		if err := format.Node(&buf, fset, expr); err == nil {
			return buf.String()
		}
		return "nil"
	case *ast.UnaryExpr:
		return t.Op.String() + formatExpr(fset, t.X)
	case *ast.BinaryExpr:
		return formatExpr(fset, t.X) + " " + t.Op.String() + " " + formatExpr(fset, t.Y)
	default:
		return "nil"
	}
}

func parseTestCaseLit(fset *token.FileSet, lit *ast.CompositeLit) (TestCase, bool) {
	tc := TestCase{Args: make(map[string]string), Want: make(map[string]string)}
	for _, elt := range lit.Elts {
		kv, ok := elt.(*ast.KeyValueExpr)
		if !ok {
			continue
		}
		key, ok := kv.Key.(*ast.Ident)
		if !ok {
			continue
		}
		switch {
		case key.Name == "name":
			if bl, ok := kv.Value.(*ast.BasicLit); ok {
				tc.Name = strings.Trim(bl.Value, "\"")
			}
		case key.Name == "args":
			if argsLit, ok := kv.Value.(*ast.CompositeLit); ok {
				for _, a := range argsLit.Elts {
					akv, ok := a.(*ast.KeyValueExpr)
					if !ok {
						continue
					}
					ak, ok := akv.Key.(*ast.Ident)
					if !ok {
						continue
					}
					tc.Args[ak.Name] = formatExpr(fset, akv.Value)
				}
			}
		case key.Name == "wantErr":
			if id, ok := kv.Value.(*ast.Ident); ok && id.Name == "true" {
				tc.WantErr = true
			} else {
				tc.WantErr = false
			}
		case strings.HasPrefix(key.Name, "want"):
			tc.Want[key.Name] = formatExpr(fset, kv.Value)
		}
	}
	if tc.Name == "" {
		return tc, false
	}
	return tc, true
}

func collectCasesFromLit(fset *token.FileSet, lit *ast.CompositeLit, cases *[]TestCase) {
	for _, elt := range lit.Elts {
		inner, ok := elt.(*ast.CompositeLit)
		if !ok {
			continue
		}
		if _, isArray := inner.Type.(*ast.ArrayType); isArray {
			collectCasesFromLit(fset, inner, cases)
			continue
		}
		if tc, ok := parseTestCaseLit(fset, inner); ok {
			*cases = append(*cases, tc)
		}
	}
}

// ParseGoTestCases parses test-case composite literals from an LLM response.
func ParseGoTestCases(response string) ([]TestCase, error) {
	code := cleanResponse(response)
	wrapped := "package test\n" +
		"\n" +
		"type testCase struct {\n" +
		"\tname string\n" +
		"\targs interface{}\n" +
		"}\n" +
		"\n" +
		"var cases = []interface{}{\n" +
		code + "\n" +
		"}\n"
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, "test.go", wrapped, parser.AllErrors)
	if err != nil {
		return nil, fmt.Errorf("parse Go code: %w", err)
	}
	var cases []TestCase
	ast.Inspect(f, func(n ast.Node) bool {
		if lit, ok := n.(*ast.CompositeLit); ok {
			// Only process the outermost composite literal (the wrapper);
			// collectCasesFromLit recurses into nested arrays itself.
			if len(cases) == 0 {
				collectCasesFromLit(fset, lit, &cases)
			}
			return false
		}
		return true
	})
	if len(cases) == 0 {
		// Fall through: inspect above returns false on first node only if
		// it is a composite lit; search again in case the first composite
		// encountered produced no cases (e.g. type declaration above).
		ast.Inspect(f, func(n ast.Node) bool {
			if lit, ok := n.(*ast.CompositeLit); ok {
				var found []TestCase
				collectCasesFromLit(fset, lit, &found)
				if len(found) > 0 {
					cases = found
					return false
				}
			}
			return true
		})
	}
	if len(cases) == 0 {
		return nil, fmt.Errorf("no test cases found in response")
	}
	return cases, nil
}

func validateTestCases(fn *models.Function, cases []TestCase) error {
	expected := len(fn.TestResults())
	for _, tc := range cases {
		if len(tc.Want) != expected {
			return fmt.Errorf("test case %q has %d return values, expected %d", tc.Name, len(tc.Want), expected)
		}
		for _, param := range fn.TestParameters() {
			if _, ok := tc.Args[param.Name]; !ok {
				return fmt.Errorf("test case %q missing argument: %s", tc.Name, param.Name)
			}
		}
	}
	if len(cases) > 1 {
		seen := make(map[string]bool)
		for _, tc := range cases {
			sig := fmt.Sprintf("%v|%v", tc.Args, tc.Want)
			seen[sig] = true
		}
		if len(seen) == 1 {
			return fmt.Errorf("generated test cases have duplicate values - need more diversity")
		}
	}
	return nil
}

func (p *Provider) GenerateTestCases(fn *models.Function) ([]TestCase, error) {
	basePrompt := buildPrompt(fn, p.config.MinCases, p.config.MaxCases)
	var lastErr error
	for attempt := 0; attempt < 3; attempt++ {
		prompt := basePrompt
		if lastErr != nil {
			prompt = strings.Replace(basePrompt,
				"Output ONLY the test case array, no explanations:\n",
				fmt.Sprintf("Output ONLY the test case array, no explanations:\nPREVIOUS ATTEMPT FAILED:\n%s\n\nPlease fix the above issue.\n\n", lastErr.Error()),
				1)
		}
		response, err := p.generate(prompt)
		if err != nil {
			lastErr = err
			continue
		}
		cases, err := ParseGoTestCases(response)
		if err != nil {
			lastErr = fmt.Errorf("parse Go test cases: %w\n\nLLM Response:\n%s", err, response)
			continue
		}
		if len(cases) > p.config.MaxCases {
			cases = cases[:p.config.MaxCases]
		}
		if err := validateTestCases(fn, cases); err != nil {
			lastErr = err
			continue
		}
		return cases, nil
	}
	return nil, fmt.Errorf("failed after 3 attempts: %w", lastErr)
}
