cat > gotests.go <<'EOF'
package main

import (
	"bytes"
	"fmt"
	"os"
	"regexp"
	"strings"
	"sync"

	"gotestsclone/internal/ai"
	"gotestsclone/internal/goparser"
	"gotestsclone/internal/input"
	"gotestsclone/internal/models"
	"gotestsclone/internal/render"
)

type options struct {
	only           *regexp.Regexp
	excl           *regexp.Regexp
	exported       bool
	printInputs    bool
	subtests       bool
	parallel       bool
	named          bool
	useGoCmp       bool
	templateDir    string
	templateName   string
	templateParams map[string]interface{}
	ai             bool
	aiModel        string
	aiEndpoint     string
	aiMinCases     int
	aiMaxCases     int
}

func matches(re *regexp.Regexp, f *models.Function) bool {
	return re.MatchString(f.Name) || re.MatchString(f.FullName())
}

func (o *options) selected(f *models.Function) bool {
	if o.exported && !f.IsExported {
		return false
	}
	if o.only != nil && !matches(o.only, f) {
		return false
	}
	if o.excl != nil && matches(o.excl, f) {
		return false
	}
	return true
}

type testOutput struct {
	Path      string
	Code      []byte
	Functions []*models.Function
}

func testFilePath(src string) string {
	if strings.HasSuffix(src, "_test.go") {
		return src
	}
	return strings.TrimSuffix(src, ".go") + "_test.go"
}

func generateTests(path string, opt *options) ([]*testOutput, error) {
	files, err := input.Files(path)
	if err != nil {
		return nil, fmt.Errorf("input.Files: %w", err)
	}
	type result struct {
		out *testOutput
		err error
	}
	ch := make(chan result, len(files))
	var wg sync.WaitGroup
	for _, file := range files {
		wg.Add(1)
		go func(file string) {
			defer wg.Done()
			out, err := generateTest(file, opt)
			ch <- result{out: out, err: err}
		}(file)
	}
	wg.Wait()
	close(ch)
	var outputs []*testOutput
	var firstErr error
	for r := range ch {
		if r.err != nil {
			if firstErr == nil {
				firstErr = r.err
			}
			continue
		}
		if r.out != nil {
			outputs = append(outputs, r.out)
		}
	}
	if firstErr != nil {
		return nil, firstErr
	}
	return outputs, nil
}

func parseTestFile(p *goparser.Parser, path string, srcHeader *models.Header) (*models.Header, map[string]bool, error) {
	if _, err := os.Stat(path); err != nil {
		return nil, nil, nil
	}
	header, funcs, err := p.ParseTestFile(path)
	if err != nil {
		return nil, nil, fmt.Errorf("Parser.Parse test file: %w", err)
	}
	if header == nil {
		return nil, nil, nil
	}
	names := make(map[string]bool)
	for _, f := range funcs {
		names[f.Name] = true
	}
	if srcHeader != nil {
		header.Imports = append(header.Imports, srcHeader.Imports...)
	}
	return header, names, nil
}

func generateTest(src string, opt *options) (*testOutput, error) {
	p := &goparser.Parser{}
	srcHeader, srcFuncs, err := p.Parse(src)
	if err != nil {
		return nil, fmt.Errorf("Parser.Parse source file: %w", err)
	}
	testPath := testFilePath(src)
	existingHeader, existingNames, err := parseTestFile(p, testPath, srcHeader)
	if err != nil {
		return nil, err
	}
	var funcs []*models.Function
	for _, f := range srcFuncs {
		if existingNames[f.TestName()] {
			continue
		}
		if !opt.selected(f) {
			continue
		}
		funcs = append(funcs, f)
	}
	if len(funcs) == 0 {
		return nil, nil
	}
	header := srcHeader
	if existingHeader != nil {
		header = existingHeader
	}
	code, err := process(header, funcs, opt)
	if err != nil {
		return nil, fmt.Errorf("output.Process: %w", err)
	}
	return &testOutput{Path: testPath, Code: code, Functions: funcs}, nil
}

func process(header *models.Header, funcs []*models.Function, opt *options) ([]byte, error) {
	tmpls, err := render.LoadTemplates(opt.templateDir, opt.templateName)
	if err != nil {
		return nil, err
	}
	aiCases := make(map[*models.Function][]interface{})
	if opt.ai {
		provider, err := ai.NewProvider(ai.Config{
			Model:    opt.aiModel,
			Endpoint: opt.aiEndpoint,
			MinCases: opt.aiMinCases,
			MaxCases: opt.aiMaxCases,
		})
		if err != nil {
			return nil, fmt.Errorf("failed to create AI provider: %w", err)
		}
		if !provider.IsAvailable() {
			return nil, fmt.Errorf("AI provider ollama is not available - ensure Ollama is running at %s", opt.aiEndpoint)
		}
		for _, fn := range funcs {
			cases, err := provider.GenerateTestCases(fn)
			if err != nil {
				fmt.Fprintf(os.Stderr, "Warning: failed to generate AI test cases for %s: %v\n", fn.Name, err)
				continue
			}
			var ifaces []interface{}
			for _, c := range cases {
				ifaces = append(ifaces, c)
			}
			aiCases[fn] = ifaces
		}
	}

	var buf bytes.Buffer
	h, err := render.Header(tmpls, header)
	if err != nil {
		return nil, err
	}
	buf.Write(h)
	if len(header.Code) > 0 {
		buf.Write(header.Code)
	}
	for _, fn := range funcs {
		b, err := render.TestFunction(tmpls, fn, render.FuncOptions{
			PrintInputs:      opt.printInputs,
			Subtests:         opt.subtests,
			Parallel:         opt.parallel,
			Named:            opt.named,
			UseGoCmp:         opt.useGoCmp,
			TemplateParams:   opt.templateParams,
			AIGeneratedCases: aiCases[fn],
		})
		if err != nil {
			return nil, err
		}
		buf.Write(b)
	}

	f, err := os.CreateTemp("", "gotests_*")
	filename := "/tmp/gotests_0"
	if err == nil {
		filename = f.Name()
		f.Close()
		defer os.Remove(filename)
	}
	out, err := render.ProcessImports(filename, buf.Bytes())
	if err != nil {
		return nil, fmt.Errorf("imports.Process: %w", err)
	}
	return out, nil
}
