package render

import (
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"sync"
)

var resolveCacheMu sync.Mutex
var resolveCache = make(map[string]string)

var modCacheMu sync.Mutex
var modCacheRoot string
var modCachePath string
var modCacheReplaces map[string]string
var modCacheLoaded bool

func packageNameInDir(dir string) string {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return ""
	}
	for _, e := range entries {
		name := e.Name()
		if e.IsDir() || !strings.HasSuffix(name, ".go") || strings.HasSuffix(name, "_test.go") {
			continue
		}
		f, err := parser.ParseFile(token.NewFileSet(), filepath.Join(dir, name), nil, parser.PackageClauseOnly)
		if err == nil && f.Name != nil {
			return f.Name.Name
		}
	}
	return ""
}

func loadGoMod() (string, string, map[string]string) {
	modCacheMu.Lock()
	defer modCacheMu.Unlock()
	if modCacheLoaded {
		return modCacheRoot, modCachePath, modCacheReplaces
	}
	modCacheLoaded = true
	modCacheReplaces = make(map[string]string)
	cwd, err := os.Getwd()
	if err != nil {
		return "", "", modCacheReplaces
	}
	dir := cwd
	for {
		modFile := filepath.Join(dir, "go.mod")
		if data, err := os.ReadFile(modFile); err == nil {
			modCacheRoot = dir
			inReplaceBlock := false
			for _, line := range strings.Split(string(data), "\n") {
				trimmed := strings.TrimSpace(line)
				if i := strings.Index(trimmed, "//"); i >= 0 {
					trimmed = strings.TrimSpace(trimmed[:i])
				}
				if trimmed == "" {
					continue
				}
				if strings.HasPrefix(trimmed, "module ") || strings.HasPrefix(trimmed, "module\t") {
					fields := strings.Fields(trimmed)
					if len(fields) >= 2 {
						modCachePath = fields[1]
					}
					continue
				}
				if trimmed == "replace (" {
					inReplaceBlock = true
					continue
				}
				if inReplaceBlock && trimmed == ")" {
					inReplaceBlock = false
					continue
				}
				isReplace := inReplaceBlock
				rest := trimmed
				if strings.HasPrefix(trimmed, "replace ") {
					isReplace = true
					rest = strings.TrimSpace(strings.TrimPrefix(trimmed, "replace "))
				}
				if isReplace {
					parts := strings.Split(rest, "=>")
					if len(parts) == 2 {
						oldFields := strings.Fields(parts[0])
						newFields := strings.Fields(parts[1])
						if len(oldFields) >= 1 && len(newFields) == 1 {
							p := newFields[0]
							if !filepath.IsAbs(p) {
								p = filepath.Join(dir, p)
							}
							modCacheReplaces[oldFields[0]] = p
						}
					}
				}
			}
			return modCacheRoot, modCachePath, modCacheReplaces
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return "", "", modCacheReplaces
		}
		dir = parent
	}
}

// resolvedImportName determines the actual package name for an import
// path if it can be found locally (standard library on disk or a
// package within the enclosing Go module), otherwise "".
func resolvedImportName(path string) string {
	if path == "C" {
		return "C"
	}
	resolveCacheMu.Lock()
	defer resolveCacheMu.Unlock()
	if v, ok := resolveCache[path]; ok {
		return v
	}
	name := ""
	if isStdPath(path) {
		if goroot := runtime.GOROOT(); goroot != "" {
			name = packageNameInDir(filepath.Join(goroot, "src", filepath.FromSlash(path)))
		}
	} else {
		root, modPath, replaces := func() (string, string, map[string]string) {
			// loadGoMod takes modCacheMu; call it before this function in
			// practice via a separate path. To avoid lock ordering issues
			// we simply invoke it here while holding resolveCacheMu, as
			// it takes a different mutex.
			return loadGoMod()
		}()
		// Longest-prefix replace match.
		best := ""
		for old, localDir := range replaces {
			if path == old || strings.HasPrefix(path, old+"/") {
				if len(old) > len(best) {
					best = old
					suffix := strings.TrimPrefix(path, old)
					name = packageNameInDir(filepath.Join(localDir, filepath.FromSlash(suffix)))
				}
			}
		}
		if name == "" && modPath != "" {
			if path == modPath {
				name = packageNameInDir(root)
			} else if strings.HasPrefix(path, modPath+"/") {
				name = packageNameInDir(filepath.Join(root, filepath.FromSlash(strings.TrimPrefix(path, modPath+"/"))))
			}
		}
	}
	resolveCache[path] = name
	return name
}
